import { render } from 'solid-js/web';
import { App } from './app.jsx';
import { EXAMPLES_BASE } from './model/default-corpus.js';
import { fetchProfile, setProfile } from './model/profile.js';
import { registerDefaults } from './model-registers.js';
import { readFromUrl } from './stores/view.js';
import './app.css';

// The bundle carries the chrome language, so the render waits for it.
async function start() {
  const { profile, errors } = await fetchProfile(EXAMPLES_BASE);
  setProfile(profile);

  for (const f of errors) console.error(`profile bundle: ${f.url} — ${f.message}`);
  registerDefaults();
  readFromUrl(location.search);
  render(() => <App />, document.getElementById('app')!);
}

void start();
