import { createEffect, createMemo, createSignal, onCleanup, Show } from 'solid-js';
import { countNavRows, filterNav } from '../../model/parse.js';
import { prefGet, prefSet } from '../../model/prefs.js';
import { nav as fullNav, scopedNav } from '../../stores/corpus.js';
import { text, view } from '../../stores/view.js';
import { Tree } from './tree.jsx';
import type { NavNode } from './tree.jsx';
import { Filter } from './filter.jsx';

export const TREE_W_MIN = 200;
export const TREE_W_MAX = 560;
export const TREE_W_DEF = 280;

export const RAIL_DRAG_THRESHOLD = 40;

const clamp = (px: number) => Math.max(TREE_W_MIN, Math.min(TREE_W_MAX, Math.round(px)));

export function setTreeWidth(px: number): number {
  const w = clamp(px);
  const root = typeof document !== 'undefined' && document.documentElement;
  if (root && root.style) root.style.setProperty('--tree-w', w + 'px');
  return w;
}

function defaultOpen(): boolean {
  try { return !matchMedia('(max-width: 900px)').matches; } catch { return true; }
}

const isKeyboardClick = (e: MouseEvent) => !!e && e.detail === 0;

export interface SidenavProps {

  onJump: (ref: string) => void;
}

export function Sidenav(props: SidenavProps) {

  const [open, setOpen] = createSignal(!!prefGet('tree.open', defaultOpen()));
  const [query, setQuery] = createSignal('');

  let panel!: HTMLElement;
  let closeButton!: HTMLButtonElement;
  let railButton!: HTMLButtonElement;
  let filterField: HTMLInputElement | null = null;

  const treeNav = createMemo<NavNode[]>(
    () => (scopedNav() ?? fullNav() ?? []) as NavNode[]);
  const hasContent = () => treeNav().length > 0;
  const trimmed = () => query().trim();
  const shownNav = createMemo<NavNode[]>(
    () => (trimmed() ? filterNav(treeNav(), trimmed()) : treeNav()));
  const total = createMemo(() => countNavRows(treeNav()));
  const shown = createMemo(() => countNavRows(shownNav()));

  setTreeWidth(Number(prefGet('tree.w', TREE_W_DEF)) || TREE_W_DEF);

  createEffect(() => {
    const b = document.body;
    b.classList.toggle('tree-open', open() && hasContent());
    b.classList.toggle('tree-rail-open', !open() && hasContent());
  });
  onCleanup(() => {
    document.body.classList.remove('tree-open', 'tree-rail-open');
  });

  function applyOpen(v: boolean, options: { focusFollows?: boolean } = {}) {
    setOpen(v);
    prefSet('tree.open', v);
    if (!options.focusFollows) return;
    const target = v ? closeButton : railButton;
    if (target && !target.hidden && target.focus) target.focus();
  }

  let drag:
    | { start: number; startW: number; onRail: boolean; opened: boolean; w?: number }
    | null = null;

  function currentWidth(): number {
    const root = typeof document !== 'undefined' && document.documentElement;
    const now = root && root.style ? parseFloat(root.style.getPropertyValue('--tree-w')) : NaN;
    return Number.isFinite(now) ? now : (Number(prefGet('tree.w', TREE_W_DEF)) || TREE_W_DEF);
  }

  function startDrag(e: PointerEvent, options: { from: Element; onRail: boolean }) {

    if (e.button && e.button !== 0) return;
    drag = {
      start: Number(e.clientX) || 0, startW: currentWidth(),
      onRail: options.onRail, opened: false,
    };
    if (e.preventDefault) e.preventDefault();

    try { options.from.setPointerCapture(e.pointerId); } catch { }
  }
  function moveDrag(e: PointerEvent) {
    if (!drag) return;
    const x = Number(e.clientX) || 0;
    if (drag.onRail) {

      if (!drag.opened && x - drag.start < RAIL_DRAG_THRESHOLD) return;
      if (!drag.opened) { drag.opened = true; applyOpen(true); }
    }
    drag.w = setTreeWidth(x);
  }

  function endDrag() {
    if (!drag) return;
    const w = drag.w;
    drag = null;
    if (w) prefSet('tree.w', w);
  }

  function cancelDrag() {
    if (!drag) return;
    const { startW, onRail, opened } = drag;
    drag = null;
    setTreeWidth(startW);
    if (onRail && opened) applyOpen(false);
  }

  function onKey(e: KeyboardEvent) {

    if (e.key !== 'Escape' || !(open() && hasContent())) return;
    const a = document.activeElement;

    if (filterField && a === filterField && trimmed()) {
      setQuery('');

      if (e.preventDefault) e.preventDefault();
      if (e.stopImmediatePropagation) e.stopImmediatePropagation();
      else if (e.stopPropagation) e.stopPropagation();
      return;
    }

    const inside = !!(panel && a && panel.contains(a));
    applyOpen(false, { focusFollows: inside });
  }

  function onDragKey(e: KeyboardEvent) {
    if (e.key !== 'Escape' || !drag) return;
    if (e.preventDefault) e.preventDefault();
    if (e.stopImmediatePropagation) e.stopImmediatePropagation();
    else if (e.stopPropagation) e.stopPropagation();
    cancelDrag();
  }

  if (typeof document !== 'undefined' && document.addEventListener) {
    // Capture, and registered before onKey: with the document itself as target
    // the registration order decides which Escape wins.
    document.addEventListener('keydown', onDragKey, true);
    document.addEventListener('keydown', onKey);

    document.addEventListener('pointermove', moveDrag as EventListener);
    document.addEventListener('pointerup', endDrag);
    document.addEventListener('pointercancel', endDrag);
    onCleanup(() => {
      document.removeEventListener('keydown', onDragKey, true);
      document.removeEventListener('keydown', onKey);
      document.removeEventListener('pointermove', moveDrag as EventListener);
      document.removeEventListener('pointerup', endDrag);
      document.removeEventListener('pointercancel', endDrag);
    });
  }

  function choose(id: string) {

    if (!id || id.startsWith('__')) return;
    props.onJump(id);
  }

  return (
    <>
      <nav
        class="doc-tree"
        id="doc-tree"
        ref={panel}
        hidden={!hasContent()}
        aria-label={text('tree.aria')}
      >
        <div class="tree-head">
          <div class="tree-head-row">
            <span class="tree-title">{text('tree.title')}</span>
                        <button
              class="tree-close"
              type="button"
              ref={closeButton}
              aria-controls="doc-tree"
              aria-expanded={open()}
              aria-label={text('tree.close')}
              title={text('tree.close')}
              onClick={(e) => applyOpen(false, { focusFollows: isKeyboardClick(e) })}
            >«</button>
          </div>
          <Filter
            query={query()}
            setQuery={setQuery}
            shown={shown()}
            total={total()}
            ref={(el) => { filterField = el; }}
          />
        </div>
        <Show when={open() && hasContent()}>
          <Tree
            nav={shownNav()}
            ignoreClosed={!!trimmed()}
            selected={view.policyScope || view.setScope || null}
            onSelect={choose}
          />
        </Show>
        <div
          class="tree-resizer"
          onPointerDown={(e) => startDrag(e, { from: e.currentTarget, onRail: false })}

          onDblClick={(e) => { e.preventDefault(); applyOpen(!open()); }}
        />
      </nav>
            <button
        class="tree-rail"
        id="tree-rail"
        type="button"
        ref={railButton}
        hidden={open() || !hasContent()}
        aria-controls="doc-tree"
        aria-expanded={open()}
        aria-label={text('tree.railTip')}
        title={text('tree.railTip')}
        onClick={(e) => {

          if (open()) return;
          applyOpen(true, { focusFollows: isKeyboardClick(e) });
        }}
        onPointerDown={(e) => startDrag(e, { from: e.currentTarget, onRail: true })}
      >
        <span class="rail-label">{text('tree.title')}</span>
      </button>
    </>
  );
}
